CustomField.formula:
IF(
    AND(
        DATEVALUE(Approved_Date__c) >= DATEVALUE("2020-01-02"),
            /* Date Governor - Earliest Applicable Date */
        DATEVALUE(Approved_Date__c) <= (TODAY()-13), 
            /* Today is Greater than or Equal to 13 Days after Approval */
        Max_FICO_Score__c >= 700, 
            /* Max Fico is greater or equal to 700 */
        Annual_Revenue__c >= 1000000,
            /* Annual Revenue is greater or equal to 1000000 */
        Approval_Expiration_Date__c >= TODAY(),
            /* Check if the Expiration date has passed */
        ISPICKVAL(Status__c, "Approved"),
            /* Check if the CR is Approved */
        Opportunity__r.RecordType.Name = "Working Capital Oppty",
            /* Exclude Broker Deals */
        ISPICKVAL(Opportunity__r.Type, "NEW"),
            /* New Opportunities */
        Account__r.Initial_Lead_Source__c != "Strategic Partner",
            /* Exclude SP Sourced Accounts */
        OR(
            ISPICKVAL(Opportunity__r.StageName, "Approved - MCA"),
            ISPICKVAL(Opportunity__r.StageName, "Offer Out - MCA")
        ) /* Stage Exclusion */
    ), 
    TRUE, FALSE
)
